from typing import List

def findTheString(lcp: List[List[int]]) -> str:
    n = len(lcp)

    for i in range(n):
        if lcp[i][i] != n - i:
            return ""

    for i in range(n):
        for j in range(n):
            if lcp[i][j] != lcp[j][i]:
                return ""


    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    for i in range(n):
        for j in range(i + 1, n):
            if lcp[i][j] > 0:
                union(i, j)


    groups = {}
    for i in range(n):
        r = find(i)
        if r not in groups:
            groups[r] = []
        groups[r].append(i)




    reps = sorted(groups.keys(), key=lambda x: x)
    if len(reps) > 26:
        return ""

    word = [''] * n
    cur_char_ord = ord('a')


    for r in reps:
        ch = chr(cur_char_ord)
        cur_char_ord += 1
        for idx in groups[r]:
            word[idx] = ch




    dp = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if word[i] == word[j]:
                if i == n - 1 or j == n - 1:
                    dp[i][j] = 1
                else:
                    dp[i][j] = dp[i + 1][j + 1] + 1
            else:
                dp[i][j] = 0
            if dp[i][j] != lcp[i][j]:
                return ""
    return "".join(word)

def smallestBeautifulString(s: str, k: int) -> str:
    """
    A string is beautiful if:

    * It consists of the first `k` letters of the English lowercase alphabet.
    * It does not contain any substring of length `2` or more which is a palindrome.

    You are given a beautiful string `s` of length `n` and a positive integer `k`.

    Return the lexicographically smallest string of length `n`, which is larger
    than `s` and is beautiful. If there is no such string, return an empty string.
    """

    n = len(s)
    arr = list(s)


    def ok(i: int, c: str) -> bool:

        if i > 0 and arr[i - 1] == c:
            return False

        if i > 1 and arr[i - 2] == c:
            return False
        return True

    for i in range(n - 1, -1, -1):

        for nxt_ord in range(ord(arr[i]) + 1, ord('a') + k):
            c = chr(nxt_ord)
            if not ok(i, c):
                continue
            arr[i] = c

            for j in range(i + 1, n):
                placed = False
                for cand_ord in range(ord('a'), ord('a') + k):
                    cand = chr(cand_ord)
                    if ok(j, cand):
                        arr[j] = cand
                        placed = True
                        break
                if not placed:

                    return ""
            return "".join(arr)

    return ""

def countQuadruplets(nums: List[int]) -> int:
    n = len(nums)


    leftLess = [[0] * (n + 2) for _ in range(n)]
    freq = [0] * (n + 2)

    for j in range(n):

        running = 0
        for x in range(1, n + 1):
            running += freq[x]
            leftLess[j][x] = running
        freq[nums[j]] += 1


    rightGreater = [[0] * (n + 2) for _ in range(n)]
    freq = [0] * (n + 2)

    for k in range(n - 1, -1, -1):
        running = 0

        for x in range(n, 0, -1):
            running += freq[x]
            rightGreater[k][x] = running
        freq[nums[k]] += 1


    ans = 0
    for j in range(n):
        for k in range(j + 1, n):
            if nums[j] > nums[k]:
                ans += leftLess[j][nums[k]] * rightGreater[k][nums[j]]

    return ans

