def findValidSplit(nums: List[int]) -> int:
    """
    You are given a 0-indexed integer array `nums` of length `n`.

    A split at an index `i` where `0 <= i <= n - 2` is called valid if the product
    of the first `i + 1` elements and the product of the remaining elements are
    coprime.
    """

    def factor(n: int) -> List[int]:
        res = []
        d = 2
        while d * d <= n:
            if n % d == 0:
                res.append(d)
                while n % d == 0:
                    n //= d
            d += 1 if d == 2 else 2                                   
        if n > 1:
            res.append(n)
        return res

    n = len(nums)

    last_pos = {}
    for i, x in enumerate(nums):
        for p in factor(x):
            last_pos[p] = i

    max_reach = 0
    for i, x in enumerate(nums):
        for p in factor(x):
            if p in last_pos:
                if last_pos[p] > max_reach:
                    max_reach = last_pos[p]
        if i == max_reach and i != n - 1:
            return i

    return -1

from typing import List
from functools import lru_cache

def minCost(nums: List[int], k: int) -> int:
    """
    You are given an integer array `nums` and an integer `k`.

    Split the array into some number of non-empty subarrays. The cost of a split
    is the sum of the importance value of each subarray in the split.

    Let `trimmed(subarray)` be the version of the subarray where all numbers which
    appear only once are removed.

    The importance value of a subarray is `k + trimmed(subarray).length`.

    Return the minimum possible cost of a split of `nums`.
    """
    n = len(nums)

    @lru_cache(None)
    def dp(i: int) -> int:
        if i == n:
            return 0

        freq = {}
        dup_len = 0                              
        best = float('inf')


        for j in range(i, n):
            x = nums[j]
            prev = freq.get(x, 0)
            freq[x] = prev + 1


            if prev == 0:

                pass
            elif prev == 1:

                dup_len += 2
            else:

                dup_len += 1

            cost_here = k + dup_len + dp(j + 1)
            if cost_here < best:
                best = cost_here

        return best

    return dp(0)

