from collections import Counter

def minimumTotalCost(nums1: List[int], nums2: List[int]) -> int:
    """
    See problem description in the docstring of the user prompt.
    """
    n = len(nums1)
    conflict_indices = []
    freq = Counter()
    total_cost = 0


    for i in range(n):
        if nums1[i] == nums2[i]:
            conflict_indices.append(i)
            freq[nums1[i]] += 1
            total_cost += i


    if not conflict_indices:
        return 0


    max_val = None
    max_freq = 0
    total_conflicts = len(conflict_indices)

    for val, c in freq.items():
        if c > max_freq:
            max_freq = c
            max_val = val


    if max_freq * 2 <= total_conflicts:
        return total_cost



    extra_needed = max_freq * 2 - total_conflicts

    for i in range(n):
        if extra_needed == 0:
            break
        if nums1[i] != nums2[i] and nums1[i] != max_val and nums2[i] != max_val:
            total_cost += i
            extra_needed -= 1

    if extra_needed > 0:
        return -1

    return total_cost

from typing import List
from collections import defaultdict, deque

def magnificentSets(n: int, edges: List[List[int]]) -> int:
    """
    See problem description in the provided docstring.
    """

    g = [[] for _ in range(n + 1)]
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)

    visited = [False] * (n + 1)

    def get_component(start: int) -> List[int]:
        """Return list of nodes in the connected component of 'start'."""
        comp = []
        q = deque([start])
        visited[start] = True
        while q:
            u = q.popleft()
            comp.append(u)
            for v in g[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
        return comp

    def bfs_longest_level(src: int, allowed: set) -> int:
        """
        BFS from src restricted to 'allowed' nodes set.
        Returns number of levels needed to visit its reachable nodes.
        Also checks bipartiteness on the fly: if an edge connects
        nodes of same parity level -> impossible (return -1).
        """
        dist = {src: 0}
        q = deque([src])
        maxd = 0
        while q:
            u = q.popleft()
            du = dist[u]
            maxd = max(maxd, du)
            for v in g[u]:
                if v not in allowed:
                    continue
                if v not in dist:
                    dist[v] = du + 1
                    q.append(v)
                else:

                    if abs(dist[v] - du) != 1:
                        return -1

        return maxd + 1

    ans = 0

    for i in range(1, n + 1):
        if not visited[i]:
            comp = get_component(i)
            comp_set = set(comp)
            best = 0

            for node in comp:
                levels = bfs_longest_level(node, comp_set)
                if levels == -1:
                    return -1
                if levels > best:
                    best = levels
            ans += best

    return ans

def countPalindromes(s: str) -> int:
    """
    Given a string of digits `s`, return the number of palindromic subsequences of
    `s` having length `5`. Since the answer may be very large, return it modulo
    `10^9 + 7`.
    """
    MOD = 10**9 + 7
    n = len(s)
    if n < 5:
        return 0




    pref1 = [[0] * 10 for _ in range(n + 1)]
    pref2 = [[[0] * 10 for _ in range(10)] for _ in range(n + 1)]

    for i in range(1, n + 1):
        d = ord(s[i - 1]) - 48

        for x in range(10):
            pref1[i][x] = pref1[i - 1][x]
        for a in range(10):
            for b in range(10):
                pref2[i][a][b] = pref2[i - 1][a][b]

        for a in range(10):
            pref2[i][a][d] = (pref2[i][a][d] + pref1[i - 1][a]) % MOD
        pref1[i][d] += 1




    suff1 = [[0] * 10 for _ in range(n + 1)]
    suff2 = [[[0] * 10 for _ in range(10)] for _ in range(n + 1)]

    for i in range(n - 1, -1, -1):
        d = ord(s[i]) - 48

        for x in range(10):
            suff1[i][x] = suff1[i + 1][x]
        for a in range(10):
            for b in range(10):
                suff2[i][a][b] = suff2[i + 1][a][b]

        for b in range(10):
            suff2[i][d][b] = (suff2[i][d][b] + suff1[i + 1][b]) % MOD
        suff1[i][d] += 1




    ans = 0
    for center in range(2, n - 2):
        left_pairs = pref2[center]                                            
        right_pairs = suff2[center + 1]                                         
        for d1 in range(10):
            for d2 in range(10):
                if left_pairs[d1][d2] and right_pairs[d2][d1]:
                    ans = (ans + left_pairs[d1][d2] * right_pairs[d2][d1]) % MOD

    return ans % MOD

def componentValue(nums: List[int], edges: List[List[int]]) -> int:
    n = len(nums)
    if n == 1:
        return 0


    g = defaultdict(list)
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)

    total = sum(nums)


    divisors = []
    d = 1
    while d * d <= total:
        if total % d == 0:
            divisors.append(d)
            if d * d != total:
                divisors.append(total // d)
        d += 1


    divisors.sort()

    def can(T: int) -> bool:
        visited = [False] * n

        def dfs(u: int) -> int:
            visited[u] = True
            s = nums[u]
            for v in g[u]:
                if not visited[v]:
                    child = dfs(v)
                    if child == -1:
                        return -1
                    s += child
            if s == T:
                return 0            
            if s > T:
                return -1
            return s

        return dfs(0) == 0

    for T in divisors:
        if can(T):
            return total // T - 1

    return 0
